// Prefix native-import-workflow.js. Real WKWebView forms, SVG and WebAudio
// decoding; key events are synthetic. No pad audition or microphone input.
(() => {
 if(location.protocol!=='http:'||!['127.0.0.1','localhost','[::1]'].includes(location.hostname)||window.__samplerWaveChecks)return;window.__samplerWaveChecks=true;
 const post=window.chrome.webview.postMessage.bind(window.chrome.webview);let running=false;
 window.chrome.webview.postMessage=function(message){let result;try{result=JSON.parse(message)}catch{return post(message)}if(result.type!=='cicada-native-smoke'||!result.ok||running)return post(message);running=true;
  const checks=result.checks,query=s=>{const n=document.querySelector(s);if(!n)throw Error('Missing '+s);return n},field=n=>query('#sampler-pad-editor [name='+n+']'),handle=n=>query('[data-sampler-boundary='+n+']');
  const pause=()=>new Promise(r=>setTimeout(r,40));async function wait(fn,label){const end=performance.now()+15000;while(performance.now()<end){if(await fn())return;await pause()}throw Error('Timed out '+label)}async function state(p){const r=await fetch('/api/'+p,{cache:'no-store'});if(!r.ok)throw Error(p+': '+r.status);return r.json()}
  async function ready(){await wait(async()=>{const revision=(await state('sampler')).bankRevision;return window.__gosx?.ready&&query('#studio-shell').dataset.shellActions==='ready'&&!document.querySelector('form[data-gosx-form-state=pending],form[data-gosx-form-state=submitting]')&&query('#cicada-sampler').dataset.samplerReady==='true'&&query('#cicada-sampler').dataset.samplerBankRevision===revision&&[...document.querySelectorAll('input[name=bankRevision]')].every(input=>input.value===revision)},'current sampler bank and mounted receipts')}
  function key(name,value,extra={}){const n=handle(name);n.focus();n.dispatchEvent(new KeyboardEvent('keydown',{key:value,code:value,bubbles:true,cancelable:true,...extra}))}function equal(a,b,label){if(a!==b)throw Error(label+': '+a+' != '+b)}
  (async()=>{await ready();if(!query('#browser-sampler').open)query('#browser-sampler > summary').click();const source=(await state('state')).source,bank=await state('sampler'),initial=JSON.stringify(bank.bank),pad=bank.bank.pads[0],asset=bank.bank.sources.find(s=>s.id===pad.source).asset,step=Math.max(1,Math.floor(asset.rate_hz/1000));
   equal(query('[data-sampler-wave] svg').namespaceURI,'http://www.w3.org/2000/svg','real SVG namespace');equal(document.querySelectorAll('#cicada-sampler canvas').length,0,'no Sampler canvas');if(!query('[data-sampler-peaks]').getAttribute('d').startsWith('M'))throw Error('Waveform has no peak path');checks.push('SVG waveform uses real imported peaks with zero Sampler canvas contexts');
   key('start','ArrowRight');equal(+field('start').value,pad.start+step,'1 ms');key('start','ArrowRight',{altKey:true});equal(+field('start').value,pad.start+step+1,'one frame');key('start','End');equal(+field('start').value,pad.end-1,'exclusive end clamp');key('start','Home');equal(+field('start').value,0,'Home');key('start','ArrowRight',{altKey:true});const wanted=1;equal(+handle('start').getAttribute('aria-valuenow'),wanted,'slider value');equal(JSON.stringify((await state('sampler')).bank),initial,'local preview has no bank writes');checks.push('synthetic native keys adjust exact frames, honor exclusive limits and expose matching accessible slider values without saving');
   query('#sampler-pad-editor button[type=submit]').click();await wait(async()=>(await state('sampler')).bank.pads[0].start===wanted,'Save pad');await ready();if(!query('#browser-sampler').open)throw Error('Save pad collapsed Sampler');const undo=[...query('#sampler-sources').querySelectorAll('button')].find(n=>n.textContent==='Undo pad edit');if(!undo)throw Error('Undo pad edit unavailable');undo.click();await wait(async()=>JSON.stringify((await state('sampler')).bank)===initial,'one exact bank Undo');await ready();if(!query('#browser-sampler').open)throw Error('Undo collapsed Sampler');equal((await state('state')).source,source,'score remains exact');checks.push('native Save pad and one exact Undo retain the open Sampler, complete imported bank and original score');
   const audio=await state('audio/config');if(audio.options.inputEnabled||(await state('transport')).playing)throw Error('Unexpected microphone or transport');return {type:'cicada-native-smoke',ok:true,checks};
  })().catch(e=>({type:'cicada-native-smoke',ok:false,checks,error:String(e)+'\n'+e.stack})).then(r=>post(JSON.stringify(r)));
 };
})();
